#!/usr/bin/env python3
"""Turn 35 Wave 46: SOCIAL & MATCHMAKING LAYER - Friend Match official mechanics (code charset, 5-minute friend codes, tracked stats, 3-0 disconnect forfeit), the DLL unlock requirement and its 3-vs-6 conflict, common codes matching random players, clan 1v1 rules, the SEED matchmaking system (account creation time), official connection requirements, no co-op, and Player Recovery."""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w46')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid
def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid
os.makedirs(RAW_DIR,exist_ok=True)

# ---------- EV-451: official social layer ----------
e_sl=new_ev("FTG support 360019064438 'How do I play a Friend Match?', FTG support 360004222118 'Multiplayer Troubleshooting', App Store US DLS26 version history, r/DreamLeagueSoccer 1m3u1ho (Jul 19 2025, popular codes), 1cyq2w9 (May 23 2024, matchmaking seed), gamingonphone DLS25 friends guide, mundodls, mokoweb, trucoteca, sportsdunia DLS26 clans guide, minireview.io",
    "THE SOCIAL AND MATCHMAKING LAYER. FRIEND MATCH (OFFICIAL FTG): enter a code or word of your choosing in the text field and tap OK, then share it with your opponent who enters the same code and taps OK. CODES MAY ONLY CONTAIN A-Z, 0-9 AND THE HYPHEN, and FTG explicitly warns to pick a unique code because 'choosing one in use could see you joining the wrong match.' The feature lives behind the Dream League Live (Multiplayer) button on the home screen, and FRIEND MATCH STATS ARE TRACKED THERE TOO. ADDING FRIENDS uses a CLOSED internal identification system - you CANNOT search by username and CANNOT link social media; instead you tap your player profile (top right), the Friends icon (bottom left), then Generate Code, and the resulting code EXPIRES AFTER A MAXIMUM OF 5 MINUTES. Your friend enters it from 'Add account', after which you both appear in each other's friends lists with divisions visible. Codes are reported to be case-insensitive and between 3 and 31 characters. THE CONNECTION PENALTY: if either player loses connection during a friendly, the game automatically awards a 3-0 victory to the player with the more stable connection - so a weak connection does not just fail the match, it hands your opponent a win. THE UNLOCK REQUIREMENT: Dream League Live and Friend Match unlock only after completing SIX Career mode matches. One guide contradicts itself inside a single article, stating six in one sentence and three in another; the six-match figure is the one repeated independently. A PRACTICAL WARNING: because the code is a shared lobby key rather than a private invitation, entering a POPULAR code such as 12345 will match you against a RANDOM player at a random time, not necessarily your friend. CLAN 1v1: you and your opponent must be in the SAME clan; you then go to Dream League Live, hit the Clan option, and select the member you want to challenge. THE SEED MATCHMAKING SYSTEM is the most consequential matchmaking discovery: matching is based on a SEED determined by your REGION AND, MORE IMPORTANTLY, THE TIME YOU STARTED YOUR ACCOUNT. Seeds divide players into small packets so the matchmaker does not have to scan the whole world, which is why OG accounts created years apart still end up in the same Live pool. Within a seed, the server first tries to match you with someone from your own tier, and only on rare occasions - when nobody is available in your tier - will it match you across tiers. Internet connection quality is the other priority factor: the weaker the connection, the less likely you are to be matched at all. OFFICIAL CONNECTION GUIDANCE: DLS has low bandwidth demands for multiplayer but is SENSITIVE TO HIGH LATENCY AND PACKET LOSS, so cellular and satellite connections can fail despite good bandwidth; official troubleshooting also confirms there is no way to invite Facebook friends, and that local multiplayer requires the same platform (Android to Android or iOS to iOS) on the same Wi-Fi router. NO CO-OP: DLS26 has no co-operative multiplayer. Summer Spotlight added 'more friend match options - add friends and play games more easily' and a PLAYER RECOVERY feature ('Changed your mind?'), the latter being the official name for the recovery tab that underpins the gacha probability method.",
    "evidence/raw/turn35_w46/EV-451_social_matchmaking.html",
    "FRIEND MATCH (OFFICIAL): enter any code/word, share it, opponent enters the same and both tap OK. Codes may only contain A-Z, 0-9 and the hyphen; FTG warns to pick a unique code because one already in use can join the WRONG match. Lives behind the DLL (Multiplayer) button; friend-match stats are tracked there. ADDING FRIENDS is a CLOSED internal system - no username search, no social-media linking: profile (top right) > Friends (bottom left) > Generate Code, and the code EXPIRES AFTER 5 MINUTES. Codes are case-insensitive, 3-31 characters. CONNECTION PENALTY: if either side disconnects, the game awards a 3-0 win to the player with the more stable connection. DLL UNLOCK: requires SIX Career matches (one guide self-contradicts with three). POPULAR CODES like 12345 will match you with a RANDOM player, not your friend. CLAN 1v1 requires both players in the same clan: DLL > Clan > select member. SEED MATCHMAKING: your seed is set by REGION and THE TIME YOU STARTED YOUR ACCOUNT, dividing players into small packets - which is why OG accounts still share a Live pool; within a seed the server tries your own tier first and only rarely crosses tiers. Connection quality is the other matching priority: weaker connection = less likely to be matched. OFFICIAL: DLS has low bandwidth needs but is SENSITIVE TO HIGH LATENCY AND PACKET LOSS, so cellular/satellite can fail; no Facebook friend invites; local multiplayer needs the same platform on the same router. NO CO-OP. Summer Spotlight added more friend match options and PLAYER RECOVERY ('Changed your mind?') - the official name for the recovery tab behind the gacha method",
    quality="official")

add_claim("OFFICIAL: Friend Match codes may only contain A-Z, 0-9 and the hyphen character, and FTG explicitly warns to choose a unique code because one already in use can see you joining the wrong match.", 1, "social/friend-match-codes", [e_sl])
add_claim("OFFICIAL: Friend Match stats are tracked behind the Dream League Live (Multiplayer) button on the home screen.", 1, "social/friend-match-stats", [e_sl])
add_claim("Adding friends uses a CLOSED internal identification system - there is no username search and no social-media linking. You generate a code from your profile, and that code expires after a maximum of 5 minutes.", 1, "social/adding-friends", [e_sl])
add_claim("If either player loses connection during a friendly match, the game automatically awards a 3-0 victory to the player with the more stable connection - a weak connection hands your opponent a win rather than merely failing the match.", 1, "social/disconnect-3-0", [e_sl])
add_claim("Dream League Live and Friend Match unlock only after completing SIX Career mode matches. One guide contradicts itself within a single article by stating three; the six-match figure is the one independently repeated.", 2, "social/dll-unlock-six-matches", [e_sl], notes="C-025 candidate - 3 vs 6 Career matches")
add_claim("Entering a POPULAR friend-match code such as 12345 will match you against a RANDOM player at a random time, not necessarily the friend you intended, because the code is a shared lobby key rather than a private invitation.", 2, "social/popular-codes-random", [e_sl])
add_claim("Clan 1v1 requires both players to be in the SAME clan: go to Dream League Live, hit the Clan option, and select the member you want to challenge.", 2, "social/clan-1v1", [e_sl])
add_claim("SEED MATCHMAKING: your Live matchmaking seed is determined by your REGION and, more importantly, THE TIME YOU STARTED YOUR ACCOUNT. Seeds divide players into small packets so the matchmaker need not scan the whole player base, which is why accounts created years apart still share a Live pool.", 2, "dll/seed-matchmaking", [e_sl], notes="Explains OG-player presence in Live")
add_claim("Within a seed the matchmaker tries your own tier first and only rarely crosses tiers when nobody is available in your tier; internet connection quality is the other matching priority, so a weaker connection makes you less likely to be matched at all.", 2, "dll/tier-first-then-cross", [e_sl])
add_claim("OFFICIAL: DLS has low multiplayer bandwidth demands but is SENSITIVE TO HIGH LATENCY AND PACKET LOSS, so cellular and satellite connections can fail despite good bandwidth. There is no way to invite Facebook friends, and local multiplayer requires the same platform (Android to Android, iOS to iOS) on the same Wi-Fi router.", 1, "social/connection-requirements", [e_sl])
add_claim("DLS26 has NO co-operative multiplayer.", 2, "social/no-coop", [e_sl])
add_claim("Summer Spotlight added a PLAYER RECOVERY feature ('Changed your mind?') - the official name for the recovery tab that underpins the gacha probability method, alongside 'more friend match options'.", 1, "social/player-recovery-official", [e_sl], notes="Officially confirms the EV-450 recovery-tab method")

p=os.path.join(RAW_DIR,'EV-451_social_matchmaking.html')
if not os.path.exists(p):
    with open(p,'w') as fh: fh.write("placeholder\n")
with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
